b:if.script:
//
/* NKS AZ ad-blocker: blocks non-user popups opened by the video host. */
(function(){
  var nativeOpen = window.open;
  var lastGesture = 0;
  function markGesture(){ lastGesture = Date.now(); }
  ['pointerdown','touchend','click','keydown'].forEach(function(ev){
    window.addEventListener(ev, markGesture, {capture:true, passive:true});
  });
  window.open = function(){
    if (Date.now() - lastGesture < 1500) { return nativeOpen.apply(window, arguments); }
    return null; /* blocked popup/popunder */
  };
})();
//

//
(function(){
  var cfg = window.NKS_CONFIG || {};
  var home = document.getElementById('nks-home');
  function esc(s){ return String(s == null ? '' : s); }

  /* ---------- Inline player ---------- */
  var overlay = document.getElementById('nks-player-overlay');
  var video = document.getElementById('nks-video');
  var plyrInstance = null;
  var wmTimer = null;
  var currentEpId = null;

  function nksShowError(msg){
    var box = document.getElementById('nks-player-err');
    box.style.display = 'block';
    box.textContent = msg;
    document.getElementById('nks-player-loading').style.display = 'none';
  }
  function nksPlaceWatermark(){
    var wm = document.getElementById('nks-watermark');
    var ip = window.nksViewerIp || 'unknown';
    var loc = window.nksViewerLoc || '';
    var dev = window.nksViewerDev || '';
    var extra = '';
    if (loc) { extra += ' • ' + loc; }
    if (dev) { extra += ' • ' + dev; }
    wm.textContent = 'NKS AZ • ' + ip + extra;
    wm.style.top = (5 + Math.random() * 80).toFixed(1) + '%';
    wm.style.left = (5 + Math.random() * 70).toFixed(1) + '%';
  }

  /* ---------- Multi-server official embeds (v1.4.0) ---------- */
  var nksEmbedTimer = null;
  var nksCurrentServer = null;
  var nksServerOrder = [];
  var nksServerResults = {};
  var nksServerFailed = {};
  var nksAutoServer = true;

  function nksProviders(){ return (window.NKS_SERVER_DATA && window.NKS_SERVER_DATA.providers) || []; }
  function nksProviderByKey(key){
    var ps = nksProviders();
    for (var i = 0; i < ps.length; i++) { if (ps[i].key === key) { return ps[i]; } }
    return null;
  }
  function nksEpisodeServerMap(id){ return ((window.NKS_SERVER_DATA && window.NKS_SERVER_DATA.episodes) || {})[id] || {}; }
  function nksConfiguredServers(id){
    var map = nksEpisodeServerMap(id);
    return nksProviders().filter(function(p){ return !!map[p.key]; });
  }
  function nksDecodeServerRef(enc, id, key){
    var clean = String(enc || '').replace(/-/g, '+').replace(/_/g, '/');
    while (clean.length % 4) { clean += '='; }
    var bin = atob(clean);
    var keyText = 'nksaz.blogspot.com|' + id + '|' + key;
    var out = '';
    for (var i = 0; i < bin.length; i++) { out += String.fromCharCode(bin.charCodeAt(i) ^ keyText.charCodeAt(i % keyText.length)); }
    try { return decodeURIComponent(escape(out)); } catch (e) { return out; }
  }
  function nksRegion(){
    var tz = '';
    try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone || ''; } catch (e) {}
    var lang = navigator.language || '';
    if (tz === 'Asia/Kolkata' || tz === 'Asia/Calcutta' || /-IN$/i.test(lang)) { return { code:'IN', label:'India' }; }
    return { code:'GLOBAL', label:'your area' };
  }
  function nksConnectionLabel(){
    var c = navigator.connection || null;
    if (!c) { return 'connection type unavailable'; }
    var bits = [];
    if (c.effectiveType) { bits.push(c.effectiveType.toUpperCase()); }
    if (typeof c.downlink === 'number') { bits.push('about ' + c.downlink + ' Mbps'); }
    if (c.saveData) { bits.push('Data Saver on'); }
    return bits.join(' • ') || 'connection type unavailable';
  }
  function nksSetServerStatus(html){
    var el = document.getElementById('nks-server-status');
    if (el) { el.innerHTML = html; }
  }
  function nksProbeServer(provider){
    if (!provider.probe) { return Promise.resolve({ ok:false, ms:9999 }); }
    return new Promise(function(resolve){
      var done = false;
      var start = performance.now();
      var img = new Image();
      var timer = setTimeout(function(){ finish(false, 4500); }, 4500);
      function finish(ok, forced){
        if (done) { return; }
        done = true;
        clearTimeout(timer);
        resolve({ ok:ok, ms:(typeof forced === 'number' ? forced : Math.round(performance.now() - start)) });
      }
      img.onload = function(){ finish(true); };
      img.onerror = function(){ finish(true); };
      img.src = provider.probe + (provider.probe.indexOf('?') >= 0 ? '&' : '?') + 'nks_probe=' + Date.now() + '_' + Math.random().toString(36).slice(2);
    });
  }
  function nksRenderServerButtons(){
    var list = document.getElementById('nks-server-list');
    if (!list || !currentEpId) { return; }
    list.innerHTML = '';
    nksConfiguredServers(currentEpId).forEach(function(p){
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'nks-server-btn' + (nksCurrentServer === p.key ? ' active' : '');
      btn.disabled = !!nksServerFailed[p.key];
      var r = nksServerResults[p.key];
      var dot = 'nks-dot';
      var sub = 'Not checked yet';
      if (nksServerFailed[p.key]) { dot += ' down'; sub = 'Failed in this session'; }
      else if (r) { dot += (r.ms <= 900 ? ' fast' : ' slow'); sub = 'Responded in about ' + r.ms + ' ms'; }
      if (nksCurrentServer === p.key) { sub = 'Now selected' + (r ? ' • about ' + r.ms + ' ms' : ''); }
      var name = document.createElement('span'); name.className = 'sn';
      var d = document.createElement('span'); d.className = 'nks-dot ' + dot.replace('nks-dot ', '').replace('nks-dot', '');
      if (dot === 'nks-dot') { d.className = 'nks-dot'; }
      name.appendChild(d);
      name.appendChild(document.createTextNode(p.label));
      var detail = document.createElement('span'); detail.className = 'sd'; detail.textContent = sub;
      btn.appendChild(name); btn.appendChild(detail);
      btn.addEventListener('click', function(){
        nksAutoServer = false;
        var autoBtn = document.getElementById('nks-auto-server');
        if (autoBtn) { autoBtn.textContent = 'Auto best server: OFF'; autoBtn.classList.remove('on'); }
        nksLoadServer(currentEpId, p.key, 'manual');
      });
      list.appendChild(btn);
    });
  }
  function nksFailCurrentServer(reason){
    if (!nksCurrentServer) { return; }
    nksServerFailed[nksCurrentServer] = true;
    if (nksEmbedTimer) { clearTimeout(nksEmbedTimer); nksEmbedTimer = null; }
    var idx = nksServerOrder.indexOf(nksCurrentServer);
    for (var i = idx + 1; i < nksServerOrder.length; i++) {
      if (!nksServerFailed[nksServerOrder[i]]) { nksLoadServer(currentEpId, nksServerOrder[i], 'fallback'); return; }
    }
    for (var j = 0; j < nksServerOrder.length; j++) {
      if (!nksServerFailed[nksServerOrder[j]]) { nksLoadServer(currentEpId, nksServerOrder[j], 'fallback'); return; }
    }
    document.getElementById('nks-player-loading').style.display = 'none';
    nksRenderServerButtons();
    nksShowError('The selected server did not start (' + reason + '), and no working backup server is left in this session. Please try again in a short while or choose a server manually.');
  }
  function nksLoadServer(id, key, reason){
    var provider = nksProviderByKey(key);
    var entry = nksEpisodeServerMap(id)[key];
    if (!provider || !entry) { return; }
    if (nksEmbedTimer) { clearTimeout(nksEmbedTimer); nksEmbedTimer = null; }
    nksCurrentServer = key;
    var frame = document.getElementById('nks-embed-frame');
    var loading = document.getElementById('nks-player-loading');
    video.style.display = 'none';
    frame.style.display = 'block';
    loading.style.display = 'flex';
    loading.lastElementChild.textContent = 'Connecting to ' + provider.label + '…';
    document.getElementById('nks-player-err').style.display = 'none';
    var result = nksServerResults[key];
    nksSetServerStatus('<b>' + provider.label + ' selected.</b> ' + (reason === 'fallback' ? 'Automatic fallback after the previous server did not start. ' : '') + nksRegion().label + ' profile • ' + nksConnectionLabel() + (result ? ' • host responded in about ' + result.ms + ' ms.' : '.'));
    nksRenderServerButtons();
    frame.src = nksDecodeServerRef(entry.enc, id, entry.provider || key);
    nksEmbedTimer = setTimeout(function(){
      if (frame.style.display !== 'none' && nksCurrentServer === key) { nksFailCurrentServer('load timeout'); }
    }, 18000);
  }
  function nksChooseServer(id){
    var configured = nksConfiguredServers(id);
    nksServerOrder = configured.map(function(p){ return p.key; });
    nksServerResults = {};
    nksServerFailed = {};
    if (!navigator.onLine) {
      document.getElementById('nks-player-loading').style.display = 'none';
      nksSetServerStatus('<b>You appear to be offline.</b> Reconnect and reopen the episode.');
      nksRenderServerButtons();
      return;
    }
    nksSetServerStatus('Checking your connection and choosing the best server…');
    nksRenderServerButtons();
    var jobs = configured.map(function(p){
      return nksProbeServer(p).then(function(r){ nksServerResults[p.key] = r; });
    });
    Promise.all(jobs).then(function(){
      var region = nksRegion();
      var scored = configured.map(function(p){
        var rank = region.code === 'IN' ? (p.india_rank || p.global_rank || 99) : (p.global_rank || 99);
        var ms = (nksServerResults[p.key] || { ms:9999 }).ms;
        return { provider:p, score:(Math.min(ms, 4500) / 45) + (rank * 18) };
      });
      scored.sort(function(a, b){ return a.score - b.score; });
      nksServerOrder = scored.map(function(x){ return x.provider.key; });
      var chosen = nksAutoServer ? scored[0].provider : configured[0];
      nksLoadServer(id, chosen.key, 'auto');
    });
  }
  function nksFindLocalEpisode(id){
    var found = null;
    ((window.NKS_LOCAL_CATALOG && window.NKS_LOCAL_CATALOG.series) || []).forEach(function(s){
      (s.episodes || []).forEach(function(e){ if (e.id === id) { found = { series:s, episode:e }; } });
    });
    return found;
  }
  function nksOpenExternal(id){
    var configured = nksConfiguredServers(id);
    var panel = document.getElementById('nks-server-panel');
    if (!configured.length) { if (panel) { panel.style.display = 'none'; } return false; }
    if (panel) { panel.style.display = 'block'; }
    var found = nksFindLocalEpisode(id);
    if (found) {
      document.getElementById('nks-ep-title').textContent = found.episode.title || id;
      document.getElementById('nks-ep-meta').textContent = 'Season ' + found.episode.season + ' • Episode ' + found.episode.episode + ' • ' + found.series.title;
    } else {
      document.getElementById('nks-ep-title').textContent = id;
      document.getElementById('nks-ep-meta').textContent = '';
    }
    document.getElementById('nks-player-loading').style.display = 'flex';
    nksChooseServer(id);
    return true;
  }
  document.getElementById('nks-embed-frame').addEventListener('load', function(){
    var frame = document.getElementById('nks-embed-frame');
    if (!currentEpId || !nksCurrentServer || !frame.getAttribute('src')) { return; }
    if (nksEmbedTimer) { clearTimeout(nksEmbedTimer); nksEmbedTimer = null; }
    document.getElementById('nks-player-loading').style.display = 'none';
    var p = nksProviderByKey(nksCurrentServer);
    nksSetServerStatus('<b>' + (p ? p.label : 'Server') + ' loaded.</b> Press Play inside the video if it does not begin automatically. If the host shows an error, use “Try next server”.');
    nksRenderServerButtons();
  });
  document.getElementById('nks-auto-server').addEventListener('click', function(){
    nksAutoServer = !nksAutoServer;
    this.textContent = 'Auto best server: ' + (nksAutoServer ? 'ON' : 'OFF');
    this.classList.toggle('on', nksAutoServer);
    if (nksAutoServer && currentEpId && nksConfiguredServers(currentEpId).length) { nksChooseServer(currentEpId); }
  });
  document.getElementById('nks-next-server').addEventListener('click', function(){
    if (!currentEpId || !nksServerOrder.length) { return; }
    var idx = nksServerOrder.indexOf(nksCurrentServer);
    var next = nksServerOrder[(idx + 1) % nksServerOrder.length];
    if (next && next !== nksCurrentServer) { nksLoadServer(currentEpId, next, 'manual'); }
  });
  document.getElementById('nks-copy-link').addEventListener('click', function(){
    if (!currentEpId) { return; }
    var url = 'https://nksaz.blogspot.com/#watch/' + encodeURIComponent(currentEpId);
    var btn = this;
    function done(){ btn.textContent = 'Copied ✓'; setTimeout(function(){ btn.textContent = 'Copy episode link'; }, 1600); }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(url).then(done).catch(function(){ window.prompt('Copy this NKS AZ episode link:', url); });
    } else { window.prompt('Copy this NKS AZ episode link:', url); }
  });

  function nksDownload(id){
    var btn = document.getElementById('nks-dl-btn');
    btn.disabled = true;
    btn.textContent = 'Preparing…';
    fetch(cfg.BACKEND_URL + '/api/dl-token/' + encodeURIComponent(id)).then(function(r){
      if (!r.ok) { throw new Error('HTTP ' + r.status); }
      return r.json();
    }).then(function(data){
      var url = data.short_url;
      if (!url) { url = data.download_url; }
      location.href = url;
    }).catch(function(err){
      nksShowError('Could not prepare download: ' + err.message);
      btn.disabled = false;
      btn.innerHTML = '&#8681; Download episode';
    });
  }
  function openPlayer(id){
    if (!id) { return; }
    currentEpId = id;
    var nksPanelReset = document.getElementById('nks-server-panel');
    if (nksPanelReset) { nksPanelReset.style.display = 'none'; }
    var nksFrameReset = document.getElementById('nks-embed-frame');
    if (nksFrameReset) { nksFrameReset.removeAttribute('src'); nksFrameReset.style.display = 'none'; }
    video.style.display = 'block';
    nksCurrentServer = null;
    nksServerFailed = {};
    overlay.classList.add('open');
    document.body.style.overflow = 'hidden';
    document.getElementById('nks-ep-title').textContent = 'Loading…';
    document.getElementById('nks-ep-meta').textContent = '';
    document.getElementById('nks-player-err').style.display = 'none';
    document.getElementById('nks-player-loading').style.display = 'flex';
    var dlBtn = document.getElementById('nks-dl-btn');
    dlBtn.disabled = true;
    dlBtn.innerHTML = '&#8681; Download episode';
    dlBtn.onclick = function(){ nksDownload(currentEpId); };
    if (nksOpenExternal(id)) {
      nksPlaceWatermark();
      if (wmTimer) { clearInterval(wmTimer); }
      wmTimer = setInterval(nksPlaceWatermark, 8000);
      return;
    }
    nksPlaceWatermark();
    if (wmTimer) { clearInterval(wmTimer); }
    wmTimer = setInterval(nksPlaceWatermark, 8000);
    fetch(cfg.BACKEND_URL + '/watch/' + encodeURIComponent(id)).then(function(r){
      if (!r.ok) { throw new Error('Episode not found (HTTP ' + r.status + ').'); }
      return r.json();
    }).then(function(data){
      document.getElementById('nks-ep-title').textContent = data.title || id;
      var nksTopTitle = document.getElementById('nks-player-top-title');
      if (nksTopTitle) { nksTopTitle.textContent = data.title || id; }
      window.nksViewerIp = data.viewer_ip || 'unknown';
      window.nksViewerLoc = data.viewer_location || '';
      window.nksViewerDev = data.viewer_device || '';
      nksPlaceWatermark();
      var done = function(){ return data; };
      return fetch(cfg.BACKEND_URL + '/api/catalog').then(function(x){ return x.json(); }).then(function(cat){
        var found = null;
        (cat.series || []).forEach(function(s){
          (s.episodes || []).forEach(function(e){ if (e.id === id) { found = e; } });
        });
        if (found) {
          document.getElementById('nks-ep-meta').textContent = 'Season ' + found.season + ' • Episode ' + found.episode;
        }
        return done();
      }).catch(function(){ return done(); });
    }).then(function(data){
      // Prefer HLS (30s chunks, faster start) if available, fallback to MP4
      // If HLS fails (e.g. server can't generate segments), fallback to MP4
      var hlsUrl = data.hls_url;
      var mp4Url = data.stream_url;
      var hlsFailed = false;
      function useMp4Fallback() {
        if (hlsFailed) return;
        hlsFailed = true;
        if (window.nksHls) { try { window.nksHls.destroy(); } catch(e){} window.nksHls = null; }
        video.src = mp4Url;
      }
      if (hlsUrl && window.Hls && window.Hls.isSupported()) {
        if (window.nksHls) { try { window.nksHls.destroy(); } catch(e){} }
        window.nksHls = new Hls({ maxBufferLength: 60 });
        window.nksHls.on(Hls.Events.ERROR, function(event, errData) {
          if (errData.fatal) { useMp4Fallback(); }
        });
        // If HLS doesn't start within 15s, fallback to MP4
        setTimeout(function() {
          if (video.readyState === 0 && !hlsFailed) { useMp4Fallback(); }
        }, 15000);
        window.nksHls.loadSource(hlsUrl);
        window.nksHls.attachMedia(video);
      } else if (hlsUrl && video.canPlayType('application/vnd.apple.mpegurl')) {
        // Safari native HLS
        video.src = hlsUrl;
        video.addEventListener('error', function() { useMp4Fallback(); }, { once: true });
      } else {
        video.src = mp4Url;
      }
      if (window.Plyr) {
        if (plyrInstance) { plyrInstance.destroy(); }
        plyrInstance = new Plyr(video, { controls: ['play-large','play','progress','current-time','mute','volume','settings','fullscreen'], disableContextMenu: true });
      }
      video.addEventListener('playing', function(){ document.getElementById('nks-player-loading').style.display = 'none'; }, { once:true });
      video.addEventListener('error', function(){ nksShowError('Stream failed to load. Please close and try again.'); });
      document.getElementById('nks-dl-btn').disabled = false;
    }).catch(function(err){
      nksShowError('Could not load this episode: ' + err.message);
    });
  }
  function closePlayer(){
    overlay.classList.remove('open');
    document.body.style.overflow = '';
    if (wmTimer) { clearInterval(wmTimer); wmTimer = null; }
    if (nksEmbedTimer) { clearTimeout(nksEmbedTimer); nksEmbedTimer = null; }
    var nksFrameClose = document.getElementById('nks-embed-frame');
    if (nksFrameClose) { nksFrameClose.removeAttribute('src'); nksFrameClose.style.display = 'none'; }
    video.style.display = 'block';
    nksCurrentServer = null;
    nksServerFailed = {};
    try { video.pause(); } catch (e) {}
    video.removeAttribute('src');
    video.load();
    if (plyrInstance) { plyrInstance.destroy(); plyrInstance = null; }
    if (window.nksHls) { try { window.nksHls.destroy(); } catch(e){} window.nksHls = null; }
    currentEpId = null;
  }
  document.getElementById('nks-player-close').addEventListener('click', closePlayer);
  document.getElementById('nks-player-video').addEventListener('contextmenu', function(e){ e.preventDefault(); });
  /* Episode card clicks (cards are rendered dynamically below) */
  home.addEventListener('click', function(ev){
    var t = ev.target;
    var a = null;
    if (t.closest) { a = t.closest('a.nks-card'); }
    if (a) {
      ev.preventDefault();
      openPlayer(a.getAttribute('data-ep'));
    }
  });

  (window.NKS_LOCAL_CATALOG ? Promise.resolve(window.NKS_LOCAL_CATALOG) : fetch(cfg.BACKEND_URL + '/api/catalog').then(function(r){return r.json();})).then(function(cat){
    var series = cat.series || [];
    if (!series.length) { home.innerHTML = '<div class="nks-loading">Nothing here yet — check back soon.</div>'; return; }
    var html = '';
    html += '<section class="nks-section" id="series"><h2>Choose a series</h2>' +
            '<p class="nks-sub">What are you in the mood for?</p><div class="nks-series-grid">';
    series.forEach(function(s, i){
      var n = (s.episodes || []).length;
      var art = s.poster_url
        ? '<img src="' + esc(s.poster_url) + '" alt=""/>'
        : '<img src="' + NKS_COMING_SOON + '" alt="Coming soon"/>';
      var bg = 'background:linear-gradient(135deg,' +
        ['#5a2b8f,#2e90de', '#8f2b4a,#e50914', '#0f6b5c,#2e90de'][i % 3] + ')';
      html += '<a class="nks-series-card" href="#series-' + esc(s.id) + '">' +
              '<div class="nks-series-art" style="' + bg + '">' + art + '</div>' +
              '<div class="nks-series-body"><h3></h3><p></p>' +
              '<span class="nks-count">' + n + (n === 1 ? ' episode' : ' episodes') + '</span></div></a>';
    });
    html += '</div></section>';
    series.forEach(function(s){
      var eps = s.episodes || [];
      html += '<section class="nks-section" id="series-' + esc(s.id) + '"><h2></h2>';
      if (s.description) html += '<p class="nks-sub"></p>';
      if (!eps.length) {
        html += '<div class="nks-coming">Episodes coming soon.</div>';
      } else {
        html += '<div class="nks-grid">';
        eps.forEach(function(e){
          var poster = e.poster_url ? '<img src="' + esc(e.poster_url) + '" alt=""/>' : '<img src="' + NKS_COMING_SOON + '" alt="Coming soon"/>';
          html += '<a class="nks-card" href="#watch" data-ep="' + esc(e.id) + '">' +
                  '<div class="nks-poster">' + poster + '<div class="nks-play"></div></div>' +
                  '<div class="nks-card-body"><h3></h3>' +
                  '<div class="nks-card-meta">S' + esc(e.season) + ' &#183; E' + esc(e.episode) + '</div></div></a>';
        });
        html += '</div>';
      }
      html += '</section>';
    });
    home.innerHTML = html;
    var si = 0;
    series.forEach(function(s){
      var card = home.querySelectorAll('.nks-series-card')[si];
      card.querySelector('h3').textContent = s.title || 'Untitled series';
      card.querySelector('p').textContent = s.description || '';
      var sec = document.getElementById('series-' + s.id);
      sec.querySelector('h2').textContent = s.title || 'Untitled series';
      if (s.description) sec.querySelector('.nks-sub').textContent = s.description;
      var cards = sec.querySelectorAll('.nks-card');
      (s.episodes || []).forEach(function(e, j){
        cards[j].querySelector('h3').textContent = e.title || 'Untitled';
      });
      si++;
    });
    var first = null;
    series.forEach(function(s){ var eps = s.episodes || []; if (!first) { if (eps.length) { first = eps[0]; } } });
    if (first) {
      var heroArt = document.getElementById('nks-hero-art');
      if (heroArt) {
        heroArt.innerHTML = first.poster_url ? '<img src="' + esc(first.poster_url) + '" alt=""/>' : '<span>&#9654;</span>';
      }
      document.getElementById('nks-hero-title').textContent = first.title;
      document.getElementById('nks-hero-desc').textContent = first.description || '';
      document.getElementById('nks-hero-play').innerHTML = '&#9654; Play Now';
      document.getElementById('nks-hero-play').addEventListener('click', function(ev){
        ev.preventDefault();
        openPlayer(first.id);
      });
    }
    var nksHash = location.hash.match(/^#watch\/([A-Za-z0-9_-]+)/);
    if (nksHash) { setTimeout(function(){ openPlayer(nksHash[1]); }, 50); }
  }).catch(function(){
    home.innerHTML = '<div class="nks-loading">Could not reach the streaming server — it may be waking up. Try again in a minute.</div>';
  });

  /* Nostalgia: episode search (old-YouTube masthead box) */
  function nksFilter(){
    var inp = document.getElementById('nks-search');
    var q = inp ? inp.value.toLowerCase() : '';
    var cards = home.querySelectorAll('.nks-card, .nks-series-card');
    for (var i = 0; i < cards.length; i++) {
      var c = cards[i];
      c.style.display = (!q || c.textContent.toLowerCase().indexOf(q) >= 0) ? '' : 'none';
    }
  }
  var nksForm = document.getElementById('nks-search-form');
  if (nksForm) { nksForm.addEventListener('submit', function(e){ e.preventDefault(); nksFilter(); }); }
  var nksSearchInput = document.getElementById('nks-search');
  if (nksSearchInput) { nksSearchInput.addEventListener('input', nksFilter); }
})();
