body.script:
//
(function(){
  try {
    var k = 'nksaz_visits';
    var n = parseInt(localStorage.getItem(k) || '0', 10) + 1;
    localStorage.setItem(k, String(n));
    var el = document.getElementById('nks-visit-count');
    if (el) { el.textContent = 'You have visited ' + n + (n === 1 ? ' time.' : ' times.'); }
  } catch (e) {}
})();
